class PriceFeed:
    """One class that knows every kind of subscriber and what each one does."""

    KINDS = ("threshold", "drop", "every", "limit")

    def __init__(self):
        # Parallel tables, one entry per name ever registered. Keeping them in
        # step is this solution's whole maintenance burden.
        self.kind = {}
        self.arg = {}
        self.scope = {}
        self.last = {}       # name -> {symbol: last price this name was told}
        self.seen = {}       # name -> updates delivered to this name
        self.log = {}        # name -> alerts raised, in order
        self.order = []      # currently attached, in registration order
        self.active = set()

    @staticmethod
    def _valid_symbol(symbol: str) -> bool:
        return 1 <= len(symbol) <= 5 and symbol.isupper() and symbol.isalpha()

    def subscribe(self, name: str, symbol: str, kind: str, arg: int) -> bool:
        if name in self.kind or kind not in self.KINDS:
            return False
        if not (symbol == "*" or self._valid_symbol(symbol)):
            return False
        # "threshold" is a price level, so 0 is a legal one; the other three are
        # counts and amounts, where 0 is not.
        if arg < (0 if kind == "threshold" else 1):
            return False
        self.kind[name] = kind
        self.arg[name] = arg
        self.scope[name] = symbol
        self.last[name] = {}
        self.seen[name] = 0
        self.log[name] = []
        self.order.append(name)
        self.active.add(name)
        return True

    def unsubscribe(self, name: str) -> bool:
        if name not in self.active:
            return False
        self._detach(name)
        return True

    def _detach(self, name: str) -> None:
        self.active.discard(name)
        self.order.remove(name)

    def publish(self, symbol: str, price: int) -> list[str]:
        fired = []
        # Iterate a copy: a "limit" subscriber detaches itself mid-pass, and
        # mutating self.order while walking it would skip its neighbour.
        for name in list(self.order):
            if name not in self.active:
                continue
            scope = self.scope[name]
            if scope != "*" and scope != symbol:
                continue
            self.seen[name] += 1
            prev = self.last[name].get(symbol)
            self.last[name][symbol] = price
            kind, arg = self.kind[name], self.arg[name]
            # The branch the pattern removes: the feed decides, for every kind
            # it has ever heard of, what counts as an alert.
            if kind == "threshold":
                alerted = price >= arg and (prev is None or prev < arg)
            elif kind == "drop":
                alerted = prev is not None and price <= prev - arg
            elif kind == "every":
                alerted = self.seen[name] % arg == 0
            else:                                  # "limit"
                alerted = True
            if not alerted:
                continue
            self.log[name].append([symbol, price])
            fired.append(name)
            if kind == "limit" and len(self.log[name]) >= arg:
                self._detach(name)
        return fired

    def count(self) -> int:
        return len(self.order)

    def subscribers(self) -> list[str]:
        return list(self.order)

    def alerts(self, name: str) -> list[list] | None:
        if name not in self.log:
            return None
        return [list(pair) for pair in self.log[name]]

class Observer:
    """A subscriber. It owns the state its own rule needs and answers one
    question: given this update, do I raise an alert?"""

    def __init__(self, symbol: str):
        self.symbol = symbol
        self.last = {}       # per-symbol memory, needed by some rules
        self.seen = 0
        self.alerts = []
        self.done = False    # set when the subscriber wants to detach itself

    def watches(self, symbol: str) -> bool:
        return self.symbol == "*" or self.symbol == symbol

    def update(self, symbol: str, price: int) -> bool:
        self.seen += 1
        prev = self.last.get(symbol)
        self.last[symbol] = price
        if not self.fires(symbol, price, prev):
            return False
        self.alerts.append([symbol, price])
        return True

    def fires(self, symbol: str, price: int, prev: int | None) -> bool:
        raise NotImplementedError


class ThresholdObserver(Observer):
    def __init__(self, symbol: str, level: int):
        super().__init__(symbol)
        self.level = level

    def fires(self, symbol, price, prev) -> bool:
        # A crossing, not a state -- so it needs the previous price, which is
        # exactly the kind of state that has nowhere to live in the feed.
        return price >= self.level and (prev is None or prev < self.level)


class DropObserver(Observer):
    def __init__(self, symbol: str, amount: int):
        super().__init__(symbol)
        self.amount = amount

    def fires(self, symbol, price, prev) -> bool:
        return prev is not None and price <= prev - self.amount


class EveryObserver(Observer):
    def __init__(self, symbol: str, k: int):
        super().__init__(symbol)
        self.k = k

    def fires(self, symbol, price, prev) -> bool:
        return self.seen % self.k == 0


class LimitObserver(Observer):
    def __init__(self, symbol: str, cap: int):
        super().__init__(symbol)
        self.cap = cap

    def fires(self, symbol, price, prev) -> bool:
        return True

    def update(self, symbol, price) -> bool:
        fired = super().update(symbol, price)
        # The lifecycle rule lives with the subscriber that has it, not in the
        # feed's notification loop.
        if len(self.alerts) >= self.cap:
            self.done = True
        return fired


class PriceFeed:
    """The subject. It keeps subscribers in order and tells them what happened;
    it never asks what any of them is or what any of them does with it."""

    KINDS = {
        "threshold": ThresholdObserver,
        "drop": DropObserver,
        "every": EveryObserver,
        "limit": LimitObserver,
    }

    def __init__(self):
        self.known = {}      # every name ever registered -> its observer
        self.order = []      # currently attached, in registration order
        self.active = set()

    @staticmethod
    def _valid_symbol(symbol: str) -> bool:
        return 1 <= len(symbol) <= 5 and symbol.isupper() and symbol.isalpha()

    def subscribe(self, name: str, symbol: str, kind: str, arg: int) -> bool:
        if name in self.known or kind not in self.KINDS:
            return False
        if not (symbol == "*" or self._valid_symbol(symbol)):
            return False
        if arg < (0 if kind == "threshold" else 1):
            return False
        self.known[name] = self.KINDS[kind](symbol, arg)
        self.order.append(name)
        self.active.add(name)
        return True

    def unsubscribe(self, name: str) -> bool:
        if name not in self.active:
            return False
        self._detach(name)
        return True

    def _detach(self, name: str) -> None:
        self.active.discard(name)
        self.order.remove(name)

    def publish(self, symbol: str, price: int) -> list[str]:
        fired = []
        # Iterating a copy is not what the pattern fixes -- the first solution
        # needs it too. A subscriber that detaches itself mid-pass would
        # otherwise make the loop skip its neighbour.
        for name in list(self.order):
            if name not in self.active:
                continue
            obs = self.known[name]
            if not obs.watches(symbol):
                continue
            if obs.update(symbol, price):
                fired.append(name)
            if obs.done:
                self._detach(name)
        return fired

    def count(self) -> int:
        return len(self.order)

    def subscribers(self) -> list[str]:
        return list(self.order)

    def alerts(self, name: str) -> list[list] | None:
        obs = self.known.get(name)
        if obs is None:
            return None
        return [list(pair) for pair in obs.alerts]
